154:   function applyEffect(effect = {}) {
155:     if (effect.gold) state.gold = Math.max(0, state.gold + effect.gold);
156:     if (effect.health) state.health = clamp(state.health + effect.health, 0, state.maxHealth);
157:     if (effect.sanity) state.sanity = clamp(state.sanity + effect.sanity, 0, 10);
158:   }
159:   function selectChoice(choice) {
160:     if (locked || !canChoose(choice)) return;
161:     if (choice.combat) return startCombat(choice);
162:     locked = true;
163:     applyEffect(choice.effect);
164:     if (choice.flag) Object.assign(state.flags, choice.flag);
165:     if (choice.note) state.notes.push(choice.note);
166:     if (state.health <= 0) return showEnding(true);
167:     state.history.push(choice.action);
168:     state.step++;
169:     locked = false;
170:     enterStep();
171:   }
172:   function itemOwned(item) {
173:     if (item.id === 'potion' || item.id === 'tonic') return state.inventory[item.id] >= 3;
174:     if (item.id === 'weapon' || item.id === 'weapon2') return state.equipment.damage >= item.damage;
175:     if (item.id === 'armor') return state.equipment.armor >= (item.armor || (state.classId === 'caballero' ? 2 : 1));
176:     if (item.id === 'relic') return state.relics.includes(item.effect);
177:     return false;
178:   }
179:   function openShop(scheduled = false) {
180:     if (!state.classId) return;
