189:     }).join('');
190:     $('shopItems').querySelectorAll('[data-item]').forEach(button => button.addEventListener('click', () => buyItem(items[Number(button.dataset.item)])));
191:     const equipment = state.equipment.weapon ? `Arma: ${state.equipment.weapon}` : 'Sin arma equipada';
192:     const relicText = state.relics.length ? state.relics.map(effect => items.find(i => i.effect === effect)?.name).filter(Boolean).join(', ') : 'ninguna';
193:     setText('inventoryText', `Pociones: ${state.inventory.potion} · Tónicos: ${state.inventory.tonic} · ${equipment} · Reliquias: ${relicText}`);
