201:   function buyItem(item) {
202:     if (!item || state.gold < item.price || itemOwned(item)) return;
203:     state.gold -= item.price;
204:     if (item.id === 'potion' || item.id === 'tonic') state.inventory[item.id]++;
205:     if (item.damage) { state.equipment.weapon = item.name; state.equipment.damage = item.damage; }
206:     if (item.id === 'armor') state.equipment.armor = state.classId === 'caballero' ? 2 : 1;
207:     if (item.effect) {
208:       state.relics.push(item.effect);
209:       if (item.effect === 'maxHealth') { state.maxHealth += 2; state.health = Math.min(state.maxHealth, state.health + 2); }
210:     }
211:     showToast(`${item.name} adquirido.`);
212:     openShop(false);
