214:   function startCombat(choice) {
215:     const enemy = choice.combat;
216:     combat = {choice, hp:enemy.maxHp, maxHp:enemy.maxHp, guarding:false, abilityUsed:false, turn:0};
217:     setText('combatTitle', enemy.title);
218:     setText('combatDescription', enemy.description);
