223:   function updateCombat() {
224:     if (!combat) return;
225:     setText('combatPlayerValue', `${state.health} / ${state.maxHealth}`);
226:     setText('combatEnemyValue', `${combat.hp} / ${combat.maxHp}`);
227:     $('combatPlayerMeter').style.width = `${100 * state.health / state.maxHealth}%`;
228:     $('combatEnemyMeter').style.width = `${100 * combat.hp / combat.maxHp}%`;
229:     $('combatPotionButton').disabled = state.inventory.potion < 1 || state.health >= state.maxHealth;
230:     $('attackButton').disabled = locked;
231:     $('guardButton').disabled = locked;
