234:   function playerAction(action) {
235:     if (!combat || locked) return;
236:     locked = true;
237:     let message = '';
238:     if (action === 'attack') {
239:       let damage = state.equipment.damage || classes[state.classId].damage;
240:       if (state.classId === 'asesino' && !combat.abilityUsed) { damage += 2; combat.abilityUsed = true; message = ' Ataque furtivo: daño adicional.'; }
241:       combat.hp = Math.max(0, combat.hp - damage);
242:       message = `Infliges ${damage} de daño.${message}`;
243:     } else if (action === 'ability') {
244:       if (combat.abilityUsed) return locked = false;
245:       const id = state.classId;
246:       if (id === 'asesino') combat.hp = Math.max(0, combat.hp - 4);
247:       if (id === 'mago') {
248:         if (state.sanity < 1) { locked = false; return showToast('No tienes cordura suficiente para lanzar el hechizo.'); }
249:         state.sanity--;
250:         combat.hp = Math.max(0, combat.hp - 4);
251:       }
252:       if (id === 'caballero') { state.health = Math.min(state.maxHealth, state.health + 2); combat.guarding = true; }
253:       combat.abilityUsed = true;
254:       message = `${classes[id].ability}: ${id === 'caballero' ? 'recuperas vida y preparas la defensa.' : 'desatas tu poder.'}`;
255:     } else if (action === 'guard') {
256:       combat.guarding = true;
257:       message = 'Te preparas para recibir el golpe.';
258:     } else if (action === 'potion') {
259:       state.inventory.potion--;
260:       state.health = Math.min(state.maxHealth, state.health + 3);
261:       message = 'La poción te devuelve hasta 3 de vida.';
262:     } else if (action === 'flee') {
263:       setHidden($('combatBackdrop'), true);
264:       combat = null;
265:       locked = false;
266:       showToast('Te retiras del combate. La elección queda abierta.');
267:       return;
268:     }
269:     setText('combatLog', message);
270:     if (combat.hp <= 0) return finishCombat(true);
271:     const reduction = combat.guarding ? 2 : 0;
272:     combat.guarding = false;
273:     const damage = Math.max(0, (combat.choice.combat.enemyDamage || 2) - state.equipment.armor - reduction);
274:     state.health = Math.max(0, state.health - damage);
275:     combat.turn++;
276:     setText('combatLog', `${message} ${combat.choice.combat.enemyName} te inflige ${damage} de daño.`);
277:     updateStats();
278:     if (state.health <= 0) return finishCombat(false);
279:     updateCombat();
280:     locked = false;
281:   }
282:   function finishCombat(victory) {
283:     const choice = combat.choice, enemy = choice.combat;
284:     if (victory) {
285:       state.gold += enemy.reward || 0;
286:       if (state.relics.includes('combatGold')) state.gold += 2;
287:       if (state.relics.includes('combatHeal')) state.health = Math.min(state.maxHealth, state.health + 2);
288:       if (choice.flag) Object.assign(state.flags, choice.flag);
289:       if (choice.note) state.notes.push(choice.note);
290:       setText('combatLog', `${enemy.enemyName} cae. Obtienes ${enemy.reward || 0} de oro.`);
291:       state.history.push(choice.action);
292:       state.step++;
293:       setTimeout(() => {
294:         setHidden($('combatBackdrop'), true);
295:         combat = null;
296:         locked = false;
297:         enterStep();
298:       }, 800);
299:     } else {
300:       setText('combatLog', 'Caes bajo el último golpe. El camino termina aquí.');
301:       setTimeout(() => {
302:         setHidden($('combatBackdrop'), true);
303:         combat = null;
304:         locked = false;
305:         showEnding(true);
306:       }, 800);
307:     }
308:   }
