241:       let damage = state.equipment.damage || classes[state.classId].damage;
242:       if (state.classId === 'asesino' && !combat.abilityUsed) { damage += 2; combat.abilityUsed = true; message = ' Ataque furtivo: daño adicional.'; }
243:       combat.hp = Math.max(0, combat.hp - damage);
244:       message = `Infliges ${damage} de daño.${message}`;
245:     } else if (action === 'ability') {
246:       if (combat.abilityUsed) return locked = false;
247:       const id = state.classId;
248:       if (id === 'asesino') combat.hp = Math.max(0, combat.hp - 4);
249:       if (id === 'mago') {
250:         if (state.sanity < 1) { locked = false; return showToast('No tienes cordura suficiente para lanzar el hechizo.'); }
251:         state.sanity--;
252:         combat.hp = Math.max(0, combat.hp - 4);
253:       }
254:       if (id === 'caballero') { state.health = Math.min(state.maxHealth, state.health + 2); combat.guarding = true; }
255:       combat.abilityUsed = true;
256:       message = `${classes[id].ability}: ${id === 'caballero' ? 'recuperas vida y preparas la defensa.' : 'desatas tu poder.'}`;
257:     } else if (action === 'guard') {
258:       combat.guarding = true;
259:       message = 'Te preparas para recibir el golpe.';
260:     } else if (action === 'potion') {
261:       if (state.inventory.potion < 1 || state.health >= state.maxHealth) { locked = false; return; }
262:       state.inventory.potion--;
263:       state.health = Math.min(state.maxHealth, state.health + 3);
264:       message = 'La poción te devuelve hasta 3 de vida.';
265:     } else if (action === 'flee') {
266:       setHidden($('combatBackdrop'), true);
267:       combat = null;
268:       locked = false;
269:       showToast('Te retiras del combate. La elección queda abierta.');
270:       return;
271:     }
272:     setText('combatLog', message);
273:     if (combat.hp <= 0) return finishCombat(true);
274:     const reduction = combat.guarding ? 2 : 0;
275:     combat.guarding = false;
276:     const damage = Math.max(0, (combat.choice.combat.enemyDamage || 2) - state.equipment.armor - reduction);
277:     state.health = Math.max(0, state.health - damage);
278:     combat.turn++;
